import { test, expect } from '@playwright/test';

test.describe('User Logout Functionality', () => {
  test.beforeEach(async ({ page }) => {
    await page.goto('/login');
  });

  test('should successfully log out a user and redirect to login page', async ({ page }) => {
    // Setup: intercept login API
    await page.route('**/api/auth/login', route => {
      route.continue();
    });

    // Login with valid credentials
    const emailInput = page.getByLabel('Email');
    const passwordInput = page.getByLabel('Password');
    const loginButton = page.getByRole('button', { name: /sign in/i });

    await emailInput.fill('user@example.com');
    await passwordInput.fill('Password123!');
    await loginButton.click();

    // Wait for navigation and verify user is logged in
    await page.waitForURL('**/dashboard');
    const welcomeMessage = page.getByText(/Welcome back/i);
    await expect(welcomeMessage).toBeVisible();

    // Perform logout
    const logoutButton = page.getByRole('button', { name: /logout/i });
    await expect(logoutButton).toBeVisible();
    await logoutButton.click();

    // Verify logout success and redirect to login
    await page.waitForURL('**/login');
    await expect(page).toHaveURL(/.*\/login/);
    await expect(welcomeMessage).not.toBeVisible();
    await expect(logoutButton).not.toBeVisible();
  });

  test('should handle logout when session is already expired', async ({ page }) => {
    // Setup: intercept logout API
    await page.route('**/api/auth/logout', route => {
      route.abort('failed');
    });

    // Navigate to dashboard directly (simulating expired session)
    await page.goto('/dashboard');
    const welcomeMessage = page.getByText(/Welcome back/i);
    await expect(welcomeMessage).toBeVisible();

    // Attempt to log out
    const logoutButton = page.getByRole('button', { name: /logout/i });
    await expect(logoutButton).toBeVisible();
    await logoutButton.click();

    // Verify error message appears
    const errorMessage = page.getByText(/session expired/i);
    await expect(errorMessage).toBeVisible();

    // Verify user is redirected to login page
    await page.waitForURL('**/login');
    await expect(page).toHaveURL(/.*\/login/);
    await expect(welcomeMessage).not.toBeVisible();
  });
});
